-- ClinicApp — exemplo completo da Página da Web (opcional, banco já instalado).
-- Destino: uma única empresa com nome_fantasia Clínica Demo MultiEspecialidades.
-- Não cria empresa/usuários, não altera cadastros clínicos, não publica o site.
-- Preserva a primeira versão anterior em configuracoes.website_example_backup.
-- Reexecutar não sobrescreve novas edições: marcador website_example_seed_applied.
-- Compatibilidade validada em MariaDB; execute no banco correto após backup.
SET NAMES utf8mb4;
SET @EXAMPLE_LOCK=GET_LOCK('clinicapp_website_config',5);
SET @EXAMPLE_EID=(SELECT IF(COUNT(*)=1,MAX(id),NULL) FROM empresas WHERE nome_fantasia='Clínica Demo MultiEspecialidades');
SET @EXAMPLE_SLUG=CONCAT('exemplo-clinica-',@EXAMPLE_EID);
SET @EXAMPLE_APPLY=(@EXAMPLE_LOCK=1 AND @EXAMPLE_EID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM configuracoes WHERE empresa_id=@EXAMPLE_EID AND chave='website_example_seed_applied') AND NOT EXISTS(SELECT 1 FROM configuracoes WHERE chave='website_slug' AND valor=@EXAMPLE_SLUG AND empresa_id<>@EXAMPLE_EID));
SET @EXAMPLE_ENABLED=(SELECT valor FROM configuracoes WHERE empresa_id=@EXAMPLE_EID AND chave='especialidades_habilitadas' LIMIT 1);
SET @EXAMPLE_ENABLED=CASE WHEN @EXAMPLE_ENABLED IS NULL THEN '["medico", "dentista", "psicologia", "psiquiatria", "pediatria", "ginecologia_obstetricia", "ortopedia_traumatologia", "cardiologia", "oftalmologia", "neurologia"]' WHEN JSON_VALID(@EXAMPLE_ENABLED) THEN @EXAMPLE_ENABLED ELSE '[]' END;
SET @EXAMPLE_BASE='{"published":false,"entry_staff":true,"entry_patient":false,"example_content":true,"name":"Clínica Demo MultiEspecialidades","slug":"clinica-demo-multiespecialidades","tagline":"Cuidado próximo em cada fase da sua vida.","color":"#147d80","background":"#f5f9f8","layout":"cards","logo":"","hero_image":"","seo_title":"Clínica Demo MultiEspecialidades | Exemplo de atendimento integrado","seo_description":"Página demonstrativa de uma clínica com diferentes especialidades, apresentação da equipe e informações de atendimento. Dados ilustrativos, não utilize para agendamento real.","phone":"(00) 0000-0000","whatsapp":"","email":"contato@clinica-demo.example","address":"Rua Exemplo de Saúde, 100 — Bairro Demonstrativo\\nCidade Exemplo / UF — endereço fictício","instagram":"","hours":"Exemplo de expediente: segunda a sexta, das 8h às 18h.\\nSábados, das 8h às 12h, mediante agendamento.","cta_label":"Conheça as formas de atendimento","cta_type":"contact","footer_text":"Página de demonstração. Endereço e contatos ilustrativos. Substitua pelos dados reais antes de publicar.","sections":{"hero":{"enabled":true,"order":10,"title":"Sua saúde merece cuidado e atenção.","text":"Conheça nossa clínica, explore as especialidades e encontre os profissionais para acompanhar você e sua família. Este é um exemplo de apresentação institucional."},"about":{"enabled":true,"order":20,"title":"Um espaço para cuidar de você por inteiro.","text":"A Clínica Demo MultiEspecialidades é uma apresentação fictícia de uma clínica com diferentes áreas de atendimento em um só lugar.\\n\\nNeste exemplo, a página organiza a equipe, apresenta as especialidades e facilita o acesso às informações de atendimento. Substitua este texto pela história, estrutura, serviços e diferenciais reais da sua clínica."},"specialties":{"enabled":true,"order":30,"title":"Especialidades para diferentes necessidades.","text":"Explore as áreas de atendimento habilitadas para esta clínica. As descrições abaixo são exemplos institucionais e devem ser revisadas pela equipe antes da publicação."},"professionals":{"enabled":true,"order":40,"title":"Conheça os profissionais da nossa equipe.","text":"Os nomes, especialidades e registros são obtidos dos profissionais cadastrados e ativos nesta empresa. As apresentações são ilustrativas e podem ser personalizadas no editor."},"reviews":{"enabled":true,"order":50,"title":"Como apresentar a experiência de quem é atendido.","text":"Os cartões desta demonstração são exemplos de layout, não relatos reais. Eles aparecem somente na pré-visualização. Para o site público, cadastre depoimentos reais com autorização."},"contact":{"enabled":true,"order":60,"title":"Vamos conversar sobre o seu atendimento.","text":"Este bloco demonstra a organização dos canais de contato, localização e horários. Endereço, telefone e e-mail abaixo são fictícios. Cadastre os dados reais e habilite a Área do Paciente, se desejar receber solicitações pelo portal."},"footer":{"enabled":true,"order":70,"title":"Informações importantes","text":"Exemplo de página institucional. Não substitui consulta, diagnóstico ou atendimento de urgência. Em uma publicação real, revise os dados de responsabilidade técnica e as informações profissionais exigidas para a clínica."}},"professionals":[],"specialties":[],"reviews":[{"name":"Pessoa de exemplo 1 — fictícia","text":"Exemplo de texto para demonstrar a apresentação de um relato sobre o atendimento. Não corresponde à experiência de uma pessoa real.","rating":5,"enabled":false,"authorized":false,"example_demo":true},{"name":"Pessoa de exemplo 2 — fictícia","text":"Este cartão mostra o espaço disponível para um depoimento. Substitua por um relato real e autorizado antes de publicar.","rating":5,"enabled":false,"authorized":false,"example_demo":true},{"name":"Pessoa de exemplo 3 — fictícia","text":"Conteúdo ilustrativo para visualizar a seção de avaliações. Nenhuma avaliação foi recebida ou verificada neste exemplo.","rating":4,"enabled":false,"authorized":false,"example_demo":true}]}';
SET @EXAMPLE_SPECIALTIES=(SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('theme',c.theme,'name',c.name,'text',c.description,'enabled',JSON_EXTRACT('true','$')) ORDER BY c.sort_order),'[]') FROM (SELECT 'medico' AS theme,'Clínica Médica' AS name,'Avaliação clínica, acompanhamento de saúde e orientações para prevenção no dia a dia.' AS description,0 AS sort_order UNION ALL SELECT 'dentista' AS theme,'Odontologia' AS name,'Cuidado com a saúde bucal, avaliação odontológica e acompanhamento individualizado.' AS description,1 AS sort_order UNION ALL SELECT 'psicologia' AS theme,'Psicologia' AS name,'Espaço de escuta e acompanhamento psicológico com atenção às necessidades de cada pessoa.' AS description,2 AS sort_order UNION ALL SELECT 'psiquiatria' AS theme,'Psiquiatria' AS name,'Avaliação e acompanhamento em saúde mental, com escuta e planejamento do cuidado.' AS description,3 AS sort_order UNION ALL SELECT 'pediatria' AS theme,'Pediatria' AS name,'Acompanhamento do crescimento e desenvolvimento infantil, em diálogo com a família.' AS description,4 AS sort_order UNION ALL SELECT 'ginecologia_obstetricia' AS theme,'Ginecologia e Obstetrícia' AS name,'Acompanhamento da saúde da mulher, consultas ginecológicas e cuidado durante a gestação.' AS description,5 AS sort_order UNION ALL SELECT 'ortopedia_traumatologia' AS theme,'Ortopedia e Traumatologia' AS name,'Avaliação de queixas dos ossos, músculos e articulações, com orientação para mobilidade e recuperação.' AS description,6 AS sort_order UNION ALL SELECT 'cardiologia' AS theme,'Cardiologia' AS name,'Avaliação da saúde cardiovascular, acompanhamento e orientação sobre fatores de risco.' AS description,7 AS sort_order UNION ALL SELECT 'oftalmologia' AS theme,'Oftalmologia' AS name,'Avaliação da saúde dos olhos, acompanhamento da visão e orientações para o cuidado ocular.' AS description,8 AS sort_order UNION ALL SELECT 'neurologia' AS theme,'Neurologia' AS name,'Avaliação de sintomas neurológicos e acompanhamento individualizado das condições do sistema nervoso.' AS description,9 AS sort_order) c WHERE JSON_CONTAINS(@EXAMPLE_ENABLED,JSON_QUOTE(c.theme)));
SET @EXAMPLE_PROFESSIONALS=(SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('user_id',u.id,'name',u.nome,'role',COALESCE(NULLIF(u.especialidade,''),c.name),'registration',COALESCE(u.registro_profissional,''),'image','','text',CONCAT('Apresentação de exemplo: ',c.description,' Personalize com informações reais do profissional.'),'enabled',JSON_EXTRACT('true','$')) ORDER BY u.nome,u.id),'[]') FROM usuarios u JOIN (SELECT 'medico' AS theme,'Clínica Médica' AS name,'Avaliação clínica, acompanhamento de saúde e orientações para prevenção no dia a dia.' AS description,0 AS sort_order UNION ALL SELECT 'dentista' AS theme,'Odontologia' AS name,'Cuidado com a saúde bucal, avaliação odontológica e acompanhamento individualizado.' AS description,1 AS sort_order UNION ALL SELECT 'psicologia' AS theme,'Psicologia' AS name,'Espaço de escuta e acompanhamento psicológico com atenção às necessidades de cada pessoa.' AS description,2 AS sort_order UNION ALL SELECT 'psiquiatria' AS theme,'Psiquiatria' AS name,'Avaliação e acompanhamento em saúde mental, com escuta e planejamento do cuidado.' AS description,3 AS sort_order UNION ALL SELECT 'pediatria' AS theme,'Pediatria' AS name,'Acompanhamento do crescimento e desenvolvimento infantil, em diálogo com a família.' AS description,4 AS sort_order UNION ALL SELECT 'ginecologia_obstetricia' AS theme,'Ginecologia e Obstetrícia' AS name,'Acompanhamento da saúde da mulher, consultas ginecológicas e cuidado durante a gestação.' AS description,5 AS sort_order UNION ALL SELECT 'ortopedia_traumatologia' AS theme,'Ortopedia e Traumatologia' AS name,'Avaliação de queixas dos ossos, músculos e articulações, com orientação para mobilidade e recuperação.' AS description,6 AS sort_order UNION ALL SELECT 'cardiologia' AS theme,'Cardiologia' AS name,'Avaliação da saúde cardiovascular, acompanhamento e orientação sobre fatores de risco.' AS description,7 AS sort_order UNION ALL SELECT 'oftalmologia' AS theme,'Oftalmologia' AS name,'Avaliação da saúde dos olhos, acompanhamento da visão e orientações para o cuidado ocular.' AS description,8 AS sort_order UNION ALL SELECT 'neurologia' AS theme,'Neurologia' AS name,'Avaliação de sintomas neurológicos e acompanhamento individualizado das condições do sistema nervoso.' AS description,9 AS sort_order) c ON c.theme=CASE WHEN u.tema_preferido IN ('odontologia','odonto','odontologico') THEN 'dentista' ELSE COALESCE(u.tema_preferido,'medico') END WHERE u.empresa_id=@EXAMPLE_EID AND u.perfil='profissional' AND u.ativo=1 AND JSON_CONTAINS(@EXAMPLE_ENABLED,JSON_QUOTE(c.theme)));
SET @EXAMPLE_DOCUMENT=JSON_SET(@EXAMPLE_BASE,'$.slug',@EXAMPLE_SLUG,'$.professionals',JSON_EXTRACT(@EXAMPLE_PROFESSIONALS,'$'),'$.specialties',JSON_EXTRACT(@EXAMPLE_SPECIALTIES,'$'));
START TRANSACTION;
INSERT INTO configuracoes(empresa_id,chave,valor) SELECT @EXAMPLE_EID,'website_example_backup',JSON_OBJECT('config_present',EXISTS(SELECT 1 FROM configuracoes WHERE empresa_id=@EXAMPLE_EID AND chave='website_config'),'config',(SELECT valor FROM configuracoes WHERE empresa_id=@EXAMPLE_EID AND chave='website_config' LIMIT 1),'slug_present',EXISTS(SELECT 1 FROM configuracoes WHERE empresa_id=@EXAMPLE_EID AND chave='website_slug'),'slug',(SELECT valor FROM configuracoes WHERE empresa_id=@EXAMPLE_EID AND chave='website_slug' LIMIT 1)) WHERE @EXAMPLE_APPLY ON DUPLICATE KEY UPDATE valor=valor;
INSERT INTO configuracoes(empresa_id,chave,valor) SELECT @EXAMPLE_EID,'website_config',@EXAMPLE_DOCUMENT WHERE @EXAMPLE_APPLY ON DUPLICATE KEY UPDATE valor=VALUES(valor);
INSERT INTO configuracoes(empresa_id,chave,valor) SELECT @EXAMPLE_EID,'website_slug',@EXAMPLE_SLUG WHERE @EXAMPLE_APPLY ON DUPLICATE KEY UPDATE valor=VALUES(valor);
INSERT INTO configuracoes(empresa_id,chave,valor) SELECT @EXAMPLE_EID,'website_example_seed_applied','1' WHERE @EXAMPLE_APPLY ON DUPLICATE KEY UPDATE valor=valor;
COMMIT;
SELECT RELEASE_LOCK('clinicapp_website_config');
SELECT CASE WHEN @EXAMPLE_APPLY THEN 'Exemplo carregado em rascunho. Acesse Página da Web e Visualizar versão salva.' WHEN @EXAMPLE_EID IS NULL THEN 'Nenhuma alteração: empresa demo ausente ou nome duplicado.' ELSE 'Nenhuma alteração: exemplo já aplicado, endereço em uso ou edição concorrente.' END AS resultado;
